def _flags(predicate):
    return ''.join('1' if getattr(chr(c), predicate)() else '0' for c in SAMPLE)


def named_examples():
    # ASCII, Latin-1, a titlecase (Lt) and a modifier (Lm) letter, a combining
    # mark (Mn, not a letter), CJK numeral three (a letter AND numeric), one
    # half, then letters newer than the kernel's: CJK Extension B and I,
    # Egyptian hieroglyphs, Tangut, Kawi.
    chars = ('a', 'Z', '_', '7', '\u00e9', '\u01c5', '\u02b0', '\u0301',
             '\u4e09', '\u00bd', '\U00020000', '\U0002ebf0', '\U00013000',
             '\U00017000', '\U00011f04')
    return tuple((ascii(ch), ch.isalpha(), ch.isalnum()) for ch in chars)


def whole_strings():
    return ('abc'.isalpha(), 'ab1'.isalpha(), 'ab1'.isalnum(),
            'ab\u00bd'.isalnum(), 'a b'.isalpha(), 'a b'.isalnum(),
            '\U00020000\U00013000'.isalpha(), 'x\U00017000'.isalnum(),
            ''.isalpha(), ''.isalnum())


def alpha_boundaries():
    return _flags('isalpha')


def alnum_boundaries():
    return _flags('isalnum')


CHECKS = [
    named_examples,
    whole_strings,
    alpha_boundaries,
    alnum_boundaries,
]

EXPECTED = {
    'named_examples': (("'a'", True, True), ("'Z'", True, True), ("'_'", False, False), ("'7'", False, True), ("'\\xe9'", True, True), ("'\\u01c5'", True, True), ("'\\u02b0'", True, True), ("'\\u0301'", False, False), ("'\\u4e09'", True, True), ("'\\xbd'", False, True), ("'\\U00020000'", True, True), ("'\\U0002ebf0'", True, True), ("'\\U00013000'", True, True), ("'\\U00017000'", True, True), ("'\\U00011f04'", True, True)),
    'whole_strings': (True, False, True, True, False, False, True, True, False, False),
    'alpha_boundaries': '',
    'alnum_boundaries': '',
}

RESULTS = {}
for _fn in CHECKS:
    _got = _outcome(_fn)
    _got = _got[1] if _got[0] == 'ok' else _got
    _want = EXPECTED.get(_fn.__name__)
    RESULTS[_fn.__name__] = (_got == _want) or 'got: %r' % (_got,)


if __name__ == '__main__':
    if sys.argv[1:] == ['--emit']:
        for _fn in CHECKS:
            print('    %r: %r,' % (_fn.__name__, _fn()))
    else:
        for _name in sorted(RESULTS):
            _v = RESULTS[_name]
            print('%-4s %s' % ('OK' if _v is True else 'FAIL', _name),
                  '' if _v is True else _v)
